try:
    import socket 
    import logging
    logging.basicConfig(level=logging.INFO,format="%(message)s")
    import os
    import binascii
except Exception as e:
    logging.info("[*] {}".format(e))
    os._exit(6)
def check(ip,port):
    try:
        data = b""
        s = socket.socket()
        s.settimeout(3)
        s.connect((ip,port))
        s.send(binascii.a2b_hex(data))
        get = s.recv(4096)
        if b"uid" in get:
            logging.info("[+] {} find s2-062".format(ip))
            os._exit(1)
        else:
            logging.info("[-] {} do not find s2-062".format(ip))
            os._exit(2)
    except Exception as e:
        logging.info("[*] {}".format(e))
        os._exit(4)
if __name__ == "__main__":
    import sys
    ip = sys.argv[1]
    port = sys.argv[2]
    check(ip,int(port))